INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'getimg.ai', 'assets/images/logos/getimg-ai.webp', 'https://getimg.ai', 'Єдиний робочий простір для створення та редагування зображень, відео, музики й голосу з провідними моделями ШІ — без пошуку моделей і складного налаштування.', 'getimg.ai об\'єднує в одному просторі створення зображень, відео, музики й мовлення за допомогою провідних моделей ШІ, які автоматично підбираються під завдання. Є генерація й редагування зображень, збільшення розміру та роздільності зображень і відео, зміна розміру, видалення фону, створення музики та голосу. На сайті згадано моделі GPT Image, Qwen Image, Grok Imagine та Wan, які регулярно додаються. Працювати можна як індивідуально, так і командою; усі тарифи передбачають комерційні права, а кількість кредитів на місяць та доступні моделі залежать від тарифу. Є оплата помісячно або на рік зі знижкою 20%.', 'Створення та редагування зображень різними моделями ШІ\nСтворення відео\nСтворення музики та голосу\nЗбільшення роздільності зображень і відео\nВидалення фону та зміна розміру зображень\nКомандна робота в одному просторі\nКомерційні права на всіх тарифах', 'Автори контенту та команди, які створюють зображення, відео й аудіо за допомогою ШІ', 'web', 'none', 'published', 'found', 'https://partners.dub.co/getimg-ai/apply', NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getimg.ai');
