INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'Civitai', NULL, 'https://civitai.com', 'Спільнота для пошуку, створення й обміну зображеннями та моделями ШІ: тисячі безкоштовних моделей Stable Diffusion і Flux, а також генерація власних картинок.', 'Civitai — спільнота творців генеративного ШІ, де можна знаходити безкоштовні моделі Stable Diffusion і Flux, переглядати зображення, відео та 3D-моделі, створені користувачами, і генерувати власні. На сайті є розділи моделей, зображень, відео, статей, коміксів і конкурсів. Внутрішня валюта Buzz використовується для генерації; платні членства Bronze, Silver і Gold дають щомісячні Buzz, безрекламний перегляд, пріоритетну генерацію, приватні моделі, ранній доступ до нових функцій і програму для авторів, у якій можна заробляти на своїх моделях.', 'Каталог безкоштовних моделей Stable Diffusion і Flux\nГенерація зображень на сайті\nГалереї зображень, відео та 3D-моделей спільноти\nВнутрішня валюта Buzz для генерації\nПлатні членства з пріоритетною генерацією та приватними моделями\nПрограма для авторів моделей', 'Творці й любителі генеративного ШІ, які шукають моделі та діляться роботами', 'web', 'basic', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'civitai.com');
