INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Silver', 25, 'month', '25 000 Green Buzz на місяць, 10 приватних моделей, преміум-підтримка' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Gold', 50, 'month', '50 000 Green Buzz на місяць' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'Pixlr', 'assets/images/logos/pixlr-com.webp', 'https://pixlr.com', 'Безкоштовний онлайн-фоторедактор і генератор зображень зі ШІ: редагуйте фото, створюйте картинки й відео за текстом, міняйте обличчя та прибирайте фон прямо в браузері.', 'Pixlr — набір онлайн-редакторів фото, інструментів дизайну та функцій ШІ, які працюють у браузері без встановлення. Можна редагувати й покращувати фото, створювати зображення й відео за текстовим описом, замінювати обличчя, видаляти фон і об\'єкти, робити колажі, заповнювати або розширювати зображення генеративними інструментами та збільшувати роздільність. Є асистент, який змінює зображення за описом словами. Для генерації використовуються різні моделі, зокрема Flux, Kling, Recraft, Google Veo та Stable Diffusion. Базові можливості безкоштовні, платні плани додають більше кредитів ШІ, приватний режим, бібліотеку шрифтів і шаблонів та відсутність реклами.', 'Створення зображень і відео за текстовим описом\nРедагування фото ШІ: заміна об\'єктів, видалення фону\nГенеративне заповнення та розширення зображень\nЗаміна облич і фотоколажі\nЗбільшення роздільності зображень\nКілька моделей ШІ на вибір', 'Усі, хто редагує фото й створює зображення, від новачків до авторів контенту', 'web', 'none', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pixlr.com');
