INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Ultra Max', 49.99, 'month', '$39.99 за місяць при оплаті за рік' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'DeepAI', NULL, 'https://deepai.org', 'Універсальна платформа зі ШІ: створення зображень, відео, музики й голосу, редагування фото та розмовний чат — просто в браузері, без обов\'язкової реєстрації.', 'DeepAI — платформа творчих інструментів зі штучним інтелектом, що працює в браузері. За одним запитом можна створити зображення, відредагувати фото, зробити коротке відео, скласти музику або поспілкуватися з AI-чатом голосом. Є генератор зображень, редактор фото, видалення фону, розфарбування чорно-білих фото, підвищення роздільності, а також інструменти для розпізнавання зображень створених ШІ й API для розробників. Спробувати можна безкоштовно й без облікового запису. Підписка DeepAI Pro за $9.99 на місяць дає великі ліміти, приватні генерації та відсутність реклами; понад ліміт витрати списуються з передоплаченого гаманця. Є мобільний застосунок і розширення для Chrome.', 'Генератор зображень за текстовим описом\nСтворення відео та музики\nРедактор фото: видалення фону, розфарбування, підвищення роздільності\nГолосовий чат зі ШІ\nAPI для розробників\nМобільний застосунок і розширення для Chrome', 'Любителі, художники та розробники, яким потрібні доступні інструменти зі ШІ', 'web,mobile', 'none', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'deepai.org');
