INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'SeaArt AI', 'assets/images/logos/seaart-ai.webp', 'https://seaart.ai', 'Універсальна платформа й спільнота для створення зображень, відео та персонажів за допомогою ШІ: генеруйте, змінюйте чужі роботи й діліться своїми.', 'SeaArt AI — спільнота творців, де ідеї перетворюються на зображення, відео та персонажів за лічені хвилини. Можна створювати зображення й відео за допомогою широкого вибору моделей (згадано Veo, Sora, Kling, Wan, Flux, Seedream, Nano Banana та інші), переробляти роботи інших користувачів у форматі «Remix», використовувати шаблони й ефекти. Є генератор зображень, збільшення роздільності, фільтри, гумка та видалення фону, а також відеофункції: рух камери, синхронізація губ, відео за референсом. Доступний мобільний застосунок SeaArt.', 'Генератор зображень і відео на різних моделях\nRemix — переробка робіт спільноти\nШаблони, ефекти й фільтри\nЗбільшення роздільності, видалення фону та об\'єктів\nВідеофункції: рух камери, синхронізація губ\nМобільний застосунок', 'Творці та любителі візуального ШІ-контенту', 'web,mobile', 'none', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'seaart.ai');
