INSERT INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @new = 1 AND c.`name` = 'Мультимедіа' AND s.`name` = 'Генерація відео';
