INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'Mage', 'assets/images/logos/mage-space.webp', 'https://mage.space', 'Безлімітний генератор зображень і відео зі ШІ прямо в браузері: безкоштовний старт, різні моделі, послідовні персонажі та режим приватності за замовчуванням.', 'Mage — безкоштовний на старті генератор зображень і відео, який працює в браузері. Підтримує багато моделей, серед яких Stable Diffusion, Flux, Qwen, Wan, Nano Banana та Veo, а також власні моделі з більшою творчою свободою. Можна створити послідовного AI-персонажа з одного референсного зображення й використовувати його в необмеженій кількості зображень і відео. Функція Motion Control переносить рух з референсного відео на персонажа. Безкоштовно можна почати, а «Gems» дозволяють запускати будь-яку модель на вимогу без підписки; преміум-членство додає необмежену генерацію, щомісячні Gems та ексклюзивні функції. Генерації приватні за замовчуванням.', 'Генерація зображень і відео в браузері\nПонад десяток моделей: Stable Diffusion, Flux, Wan, Veo та інші\nПослідовні AI-персонажі за одним референсом\nMotion Control: перенесення руху з відео на персонажа\nGems для запуску моделей на вимогу без підписки\nПриватні генерації за замовчуванням', 'Художники й автори персонажів для історій та контенту', 'web', 'none', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mage.space');
