INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'Scenario', 'assets/images/logos/scenario-com.webp', 'https://scenario.com', 'Платформа творчого ШІ для команд і розробників: власні моделі, навчені на вашому стилі, робочі процеси й доступ до сотень моделей для зображень, відео, 3D та аудіо.', 'Scenario — платформа, на якій команди будують робочі процеси для зображень, відео, аудіо й 3D або просто описують завдання, а помічник Genie виконує решту. Можна навчити власну модель на 5–100 еталонних зображень, щоб результати послідовно зберігали ваш стиль і правила бренду. Платформа дає доступ до сотень моделей від десятків постачальників, порівняння результатів поруч, візуальний редактор багатокрокових процесів, агентів, які пакетно створюють матеріали, API для розробників та MCP для агентів. Сайт заявляє відповідність SOC 2 Type II та приватність за замовчуванням.', 'Навчання власних моделей на 5–100 зображеннях\nДоступ до сотень моделей для зображень, відео, 3D й аудіо\nВізуальний редактор робочих процесів\nАгенти для пакетного створення матеріалів\nAPI для розробників і MCP для агентів\nSSO та відповідність SOC 2 Type II', 'Ігрові й творчі студії, команди дизайну та розробники, яким потрібні послідовні матеріали в єдиному стилі', 'web', 'basic', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scenario.com');
INSERT INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @new = 1 AND c.`name` = 'Мультимедіа' AND s.`name` = 'Генерація зображень';
INSERT INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @new = 1 AND c.`name` = 'Мультимедіа' AND s.`name` = '3D та анімація';
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @new = 1 AND c.`name` = 'Мультимедіа';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `internal_registration_url`, `created_at`) SELECT 'StarryAI', 'assets/images/logos/starryai-com.webp', 'https://starryai.com', 'Генератор зображень за текстом чи емодзі зі ШІ: безкоштовні щоденні картинки без водяних знаків, понад тисяча стилів і повне право власності на створене.', 'StarryAI створює зображення за вашими словами або емодзі. Щодня доступні безкоштовні зображення без водяних знаків, а після реєстрації рахунок поповнюється 5 люменами (25 зображень). Сайт підкреслює, що ви залишаєтесь власником створених зображень і маєте комерційні права. Є понад 1000 стилів і моделей, а також інструменти для покращення зображень, підвищення роздільності та видалення фону. Серед напрямів на сайті — портрети, аніме, ілюстрації, персонажі, інтер\'єри, аватари й портретні фото.', 'Генерація зображень за текстом чи емодзі\nБезкоштовні щоденні зображення без водяних знаків\nПонад 1000 стилів і моделей\nПокращення, збільшення роздільності та видалення фону\nПовне право власності й комерційні права на створене', 'Всі, хто хоче швидко створювати ШІ-зображення для творчості та особистих і комерційних проєктів', 'web', 'none', 'published', 'found', NULL, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'starryai.com');
